package pe.grafiplot.herramientas;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.*;
import android.os.*;
import android.net.Uri;
import android.widget.Toast;
import com.google.firebase.*;
import com.google.firebase.messaging.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
public final class GrafiplotPush {
 static final String TOPIC="grafiplot_clientes";
 static JSONObject config=new JSONObject();
 static Context context;
 static boolean initialized=false;
 static android.content.SharedPreferences prefs(){return context.getSharedPreferences("grafiplot_avisos",0);}
 public static synchronized void initialize(Context c){context=c.getApplicationContext();try{String cached=prefs().getString("public_config",null);if(cached!=null)config=new JSONObject(cached);else try(InputStream in=context.getAssets().open("push-config.json")){config=new JSONObject(read(in,16000));}startFirebase();}catch(Exception ignored){}new Thread(()->{try{HttpURLConnection con=(HttpURLConnection)new URL("https://vasquezpalparoy-star.github.io/grafiplot-herramientas/push-config.json").openConnection();con.setConnectTimeout(5000);con.setReadTimeout(5000);con.setUseCaches(false);try{if(con.getResponseCode()==200){JSONObject remote=new JSONObject(read(con.getInputStream(),16000));synchronized(GrafiplotPush.class){config=remote;prefs().edit().putString("public_config",remote.toString()).apply();startFirebase();}}}finally{con.disconnect();}}catch(Exception ignored){}},"grafiplot-push-config").start();}
 static String read(InputStream in,int max)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("Respuesta demasiado grande");out.write(b,0,n);}return out.toString("UTF-8");}
 static synchronized void startFirebase(){if(initialized||!configured())return;try{FirebaseOptions options=new FirebaseOptions.Builder().setApiKey(config.getString("apiKey")).setApplicationId(config.getString(BuildConfig.ADMIN_APP?"adminAndroidAppId":"androidAppId")).setGcmSenderId(config.getString("senderId")).setProjectId(config.getString("projectId")).build();if(FirebaseApp.getApps(context).isEmpty())FirebaseApp.initializeApp(context,options);FirebaseMessaging.getInstance().setAutoInitEnabled(false);channels();initialized=true;if(prefs().getBoolean("consent",false)&&permitted())subscribe();}catch(Exception ignored){}}
 public static boolean configured(){return config.optBoolean("enabled",false)&&!config.optString("projectId").isEmpty()&&!config.optString("apiKey").isEmpty()&&!config.optString(BuildConfig.ADMIN_APP?"adminAndroidAppId":"androidAppId").isEmpty()&&!config.optString("senderId").isEmpty();}
 static boolean permitted(){return ((NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE)).areNotificationsEnabled()&&(Build.VERSION.SDK_INT<33||context.checkSelfPermission("android.permission.POST_NOTIFICATIONS")==PackageManager.PERMISSION_GRANTED);}
 public static void enable(Activity activity){if(!configured()||!initialized){Toast.makeText(activity,"Los avisos todavía no están activados: falta conectar Firebase.",Toast.LENGTH_LONG).show();return;}if(Build.VERSION.SDK_INT>=33&&activity.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED){activity.requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},41);return;}prefs().edit().putBoolean("consent",true).apply();subscribe();}
 public static void subscribe(){if(!initialized||!permitted())return;channels();FirebaseMessaging.getInstance().setAutoInitEnabled(true);FirebaseMessaging.getInstance().subscribeToTopic(TOPIC).addOnCompleteListener(task->{prefs().edit().putBoolean("subscribed",task.isSuccessful()).apply();Toast.makeText(context,task.isSuccessful()?"Avisos de Grafiplot activados":"No se pudo activar. Comprueba Internet y los servicios de Google Play.",Toast.LENGTH_LONG).show();});}
 public static void granted(){prefs().edit().putBoolean("consent",true).apply();subscribe();}
 public static void disable(){prefs().edit().putBoolean("consent",false).putBoolean("subscribed",false).apply();if(initialized){FirebaseMessaging.getInstance().unsubscribeFromTopic(TOPIC);FirebaseMessaging.getInstance().setAutoInitEnabled(false);}}
 public static String status(){JSONObject out=new JSONObject();try{out.put("configured",configured());out.put("permission",permitted());out.put("subscribed",prefs().getBoolean("subscribed",false)&&prefs().getBoolean("consent",false));}catch(Exception ignored){}return out.toString();}
 public static String messages(){return prefs().getString("messages","[]");}
 public static synchronized void remember(Map<String,String> data){if(context==null)return;String id=data.get("announcement_id");if(id==null||id.length()>100)return;try{JSONArray old=new JSONArray(messages()),list=new JSONArray();JSONObject record=new JSONObject();for(String k:new String[]{"announcement_id","title","body","style","target","imageUrl"}){String v=data.get(k);record.put(k,v==null?"":v.substring(0,Math.min(v.length(),1000)));}record.put("receivedAt",System.currentTimeMillis());list.put(record);for(int i=0;i<old.length()&&list.length()<30;i++)if(!id.equals(old.getJSONObject(i).optString("announcement_id")))list.put(old.getJSONObject(i));prefs().edit().putString("messages",list.toString()).apply();}catch(Exception ignored){}}
 static void channels(){NotificationManager manager=(NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel("grafiplot_avisos","Avisos de Grafiplot",NotificationManager.IMPORTANCE_DEFAULT));manager.createNotificationChannel(new NotificationChannel("grafiplot_importante","Avisos importantes",NotificationManager.IMPORTANCE_HIGH));}
 public static void display(Context c,RemoteMessage message){context=c.getApplicationContext();Map<String,String> data=new HashMap<>(message.getData());RemoteMessage.Notification n=message.getNotification();if(n!=null){if(!data.containsKey("title"))data.put("title",n.getTitle()==null?"Grafiplot":n.getTitle());if(!data.containsKey("body"))data.put("body",n.getBody()==null?"":n.getBody());}if(!data.containsKey("announcement_id"))data.put("announcement_id",message.getMessageId()==null?UUID.randomUUID().toString():message.getMessageId());boolean chat="chat".equals(data.get("target"));if(chat){if(!GrafiplotChat.accepts(data.get("recipientUid")))return;}else remember(data);if(!permitted()||(!chat&&!prefs().getBoolean("consent",false)))return;channels();String style=data.getOrDefault("style","aviso"),id=data.get("announcement_id");Intent intent=new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);for(Map.Entry<String,String> e:data.entrySet())intent.putExtra(e.getKey(),e.getValue());PendingIntent action=PendingIntent.getActivity(context,id.hashCode(),intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder builder=new Notification.Builder(context,style.equals("importante")?"grafiplot_importante":"grafiplot_avisos").setSmallIcon(pe.grafiplot.herramientas.R.drawable.ic_notification).setContentTitle(data.getOrDefault("title","Grafiplot")).setContentText(data.getOrDefault("body","")).setColor(style.equals("promocion")?0xff177b66:0xffdf122a).setAutoCancel(true).setContentIntent(action).setStyle(new Notification.BigTextStyle().bigText(data.getOrDefault("body",""))).addAction(new Notification.Action.Builder((android.graphics.drawable.Icon)null,"Abrir",action).build());if(style.equals("imagen")){String url=data.get("imageUrl");if(url!=null&&url.startsWith("https://"))try{HttpURLConnection con=(HttpURLConnection)new URL(url).openConnection();con.setConnectTimeout(5000);con.setReadTimeout(5000);try{byte[] bytes=readBytes(con.getInputStream(),1024*1024);BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);options.inSampleSize=Math.max(1,Math.max(options.outWidth,options.outHeight)/1200);options.inJustDecodeBounds=false;Bitmap image=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(image!=null)builder.setStyle(new Notification.BigPictureStyle().bigPicture(image).setSummaryText(data.getOrDefault("body","")));}finally{con.disconnect();}}catch(Exception ignored){}}((NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE)).notify(chat?"grafiplot_chat":null,id.hashCode(),builder.build());}
 static byte[] readBytes(InputStream in,int max)throws IOException{try(InputStream stream=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=stream.read(b))!=-1){if(out.size()+n>max)throw new IOException("Imagen demasiado grande");out.write(b,0,n);}return out.toByteArray();}}
}
